use super::{
    CapturedClipboard,
    read_content::{ClipboardSnapshot, read_content},
};
use crate::source_app;
use anyhow::{Result, anyhow};
use clipboard_core::preferences::CaptureFormatPreference;
use clipboard_core::{MAX_NATIVE_FORMAT_BYTES, MAX_NATIVE_FORMAT_TOTAL_BYTES, NativeFormatCapture};
use clipboard_rs::{Clipboard, ClipboardContext};

// Password managers use these ownership-independent markers on macOS and Linux.
const PRIVATE_FORMATS: &[&str] = &[
    "org.nspasteboard.TransientType",
    "org.nspasteboard.ConcealedType",
    "org.nspasteboard.AutoGeneratedType",
    "application/x-kde-passwordManagerHint",
    "x-kde-passwordManagerHint",
    "ExcludeClipboardContentFromMonitorProcessing",
];
/// X11 选择机制的元数据格式：不是内容，不参与额外格式捕获与内容身份哈希。
#[cfg(target_os = "linux")]
pub(crate) const X11_META_FORMATS: &[&str] = &[
    "TARGETS",
    "TIMESTAMP",
    "MULTIPLE",
    "SAVE_TARGETS",
    "DELETE",
    "INCR",
];
const PRIMARY_FORMATS: &[&str] = &[
    "TARGETS",
    "TIMESTAMP",
    "MULTIPLE",
    "SAVE_TARGETS",
    "DELETE",
    "INCR",
    "UTF8_STRING",
    "STRING",
    "TEXT",
    "COMPOUND_TEXT",
    "text/plain",
    "text/plain;charset=utf-8",
    "text/plain;charset=UTF-8",
    "text/html",
    "text/rtf",
    "text/richtext",
    "text/uri-list",
    "image/png",
    "image/tiff",
    "image/bmp",
    "x-special/gnome-copied-files",
    "x-special/nautilus-clipboard",
    "public.utf8-plain-text",
    "public.utf16-plain-text",
    "public.html",
    "public.rtf",
    "public.png",
    "public.tiff",
    "public.file-url",
    "NSFilenamesPboardType",
    "com.apple.pasteboard.promised-file-url",
    "com.apple.pasteboard.promised-file-content-type",
];

/// macOS refuses to write legacy pasteboard names such as `NSStringPboardType` or
/// `CorePasteboardFlavorType 0x…`; only UTIs can be restored.
pub(crate) fn is_restorable(name: &str) -> bool {
    !cfg!(target_os = "macos") || (name.contains('.') && !name.contains(char::is_whitespace))
}

fn formats(clipboard: &ClipboardContext) -> Result<Vec<String>> {
    clipboard
        .available_formats()
        .map_err(|error| anyhow!("读取剪贴板格式失败：{error}"))
}

fn is_private(formats: &[String], clipboard: &ClipboardContext) -> bool {
    formats
        .iter()
        .any(|name| PRIVATE_FORMATS.contains(&name.as_str()))
        || (formats
            .iter()
            .any(|name| name == "CanIncludeInClipboardHistory")
            && clipboard
                .get_buffer("CanIncludeInClipboardHistory")
                .map_or(true, |value| value.as_slice() != 1u32.to_le_bytes()))
}

fn is_metadata(name: &str) -> bool {
    PRIVATE_FORMATS.contains(&name)
        || matches!(
            name,
            "TARGETS"
                | "TIMESTAMP"
                | "MULTIPLE"
                | "SAVE_TARGETS"
                | "DELETE"
                | "INCR"
                | "CanIncludeInClipboardHistory"
                | "CanUploadToCloudClipboard"
                | "org.nspasteboard.source"
                | "com.apple.pasteboard.promised-file-content-type"
        )
}

pub(super) fn read_clipboard(
    clipboard: &ClipboardContext,
    allowed: &CaptureFormatPreference,
) -> Result<ClipboardSnapshot> {
    let mut formats = formats(clipboard)?;
    if is_private(&formats, clipboard) {
        return Ok(ClipboardSnapshot {
            content: None,
            source: None,
            warning: None,
            extra: Vec::new(),
            formats: Vec::new(),
        });
    }
    let (content, warning) = read_content(
        clipboard,
        allowed,
        #[cfg(target_os = "linux")]
        Some(&formats),
    )?;
    let mut extra = Vec::new();
    let mut total = 0usize;
    if content.is_some() {
        for name in &formats {
            if !allowed.includes(name)
                || PRIMARY_FORMATS.contains(&name.as_str())
                || PRIVATE_FORMATS.contains(&name.as_str())
                || !is_restorable(name)
            {
                continue;
            }
            let Ok(data) = clipboard.get_buffer(name) else {
                continue;
            };
            if data.is_empty()
                || data.len() > MAX_NATIVE_FORMAT_BYTES
                || total + data.len() > MAX_NATIVE_FORMAT_TOTAL_BYTES
            {
                continue;
            }
            total += data.len();
            extra.push(NativeFormatCapture {
                name: name.clone(),
                data,
            });
        }
    }
    formats.retain(|name| !is_metadata(name) && allowed.includes(name));
    Ok(ClipboardSnapshot {
        content,
        source: source_app::clipboard_source(),
        warning,
        extra,
        formats,
    })
}

pub(super) fn read_current_capture(
    clipboard: &ClipboardContext,
    allowed: &CaptureFormatPreference,
) -> Result<(Option<CapturedClipboard>, Vec<String>, bool)> {
    let mut formats = formats(clipboard)?;
    if is_private(&formats, clipboard) {
        return Ok((None, Vec::new(), false));
    }
    let content = read_content(
        clipboard,
        allowed,
        #[cfg(target_os = "linux")]
        Some(&formats),
    )?
    .0;
    formats.retain(|name| !is_metadata(name) && allowed.includes(name));
    let undecidable = content.is_none()
        && allowed.allows_image()
        && formats.iter().any(|name| {
            matches!(
                name.as_str(),
                "image/png" | "image/tiff" | "image/bmp" | "public.png" | "public.tiff"
            )
        });
    Ok((content, formats, undecidable))
}

#[cfg(all(test, target_os = "macos"))]
mod tests {
    use super::is_restorable;

    #[test]
    fn legacy_pasteboard_names_are_not_restored() {
        assert!(!is_restorable("NSStringPboardType"));
        assert!(!is_restorable("CorePasteboardFlavorType 0x75747874"));
        assert!(is_restorable("public.plain-text"));
        assert!(is_restorable("com.microsoft.ole.source"));
    }
}
